  ui_story_32110401_13_dialog_content = "Não há mais ninguém por aqui agora.",
  ui_story_32110401_14_dialog_content = "Gostaria de aproveitar esta oportunidade para ver os resultados do meu treinamento com a senhorita Vice?",
  ui_story_32110401_15_dialog_content = "Claro.",
