  ui_story_32110401_36_dialog_content = "E-eu nem tive a chance de experimentá-las ainda... e agora estão todas... congeladas...",
  ui_story_32110401_37_dialog_content = "Ah... D-Desculpe!",
  ui_story_32110401_38_dialog_content = "Suspiro... Todo esse esforço, todo o trabalho duro que eu coloquei nesses últimos dias... foi tudo em vão.",
  ui_story_32110401_39_option_content = "(Dê uma sugestão específica para Zarya)",
  ui_story_32110401_40_dialog_content = "Eu tenho uma sugestão.",
  ui_story_32110401_41_dialog_content = "Antes de trabalhar na sua precisão, tente reduzir a intensidade da Lumina que você está liberando.",
