  ui_story_32110401_46_dialog_content = "Não deix isso te desanimar. Vamos deixar a mira precisa de lado por enquanto.",
  ui_story_32110401_47_dialog_content = "Talvez, se você começar reduzindo o poder do seu Lumina, sua conjuração possa ficar mais suave?",
