  ui_story_32110401_52_dialog_content = "Assim que dominar este primeiro passo, você pode aumentar gradualmente seu poder até conseguir controlá-lo totalmente.",
  ui_story_32110401_53_dialog_content = "Essa certamente é uma solução viável.",
  ui_story_32110401_54_dialog_content = "Mas isso por si só pode ser muito simples para você.",
  ui_story_32110401_55_dialog_content = "Hum?",
  ui_story_32110401_56_dialog_content = "Será que tem alguma garrafa ou lata barata por aqui...",
  ui_story_32110401_57_dialog_content = "Ah, achei um. Isso deve resolver o problema.",
  ui_story_32110401_58_dialog_content = "Por que você está colocando essa garrafa na cabeça?",
  ui_story_32110401_59_dialog_content = "Você não quer dizer...?!",
  ui_story_32110401_60_dialog_content = "Zarya, quero que você acerte a garrafa na minha cabeça com seu gelo.",
  ui_story_32110401_61_dialog_content = "Hã? Isso parece incrivelmente perigoso!",
  ui_story_32110401_62_dialog_content = "Se eu te acertasse por engano, você...!",
  ui_story_32110401_63_dialog_content = "Por que você assume que vai falhar mesmo antes de tentar?",
  ui_story_32110401_64_dialog_content = "Não se preocupe. Não é como se eu nunca tivesse sido atingido pelos seus Luminatics antes. Eu devo ter desenvolvido alguma resistência a eles até agora.",
  ui_story_32110401_65_dialog_content = "Mas...",
  ui_story_32110401_66_dialog_content = "Relaxa, Vice e eu já fizemos isso antes.",
