  ui_story_32110401_69_dialog_content = "Além disso, você faz questão de praticar suas habilidades em lugares onde não há ninguém por perto.",
  ui_story_32110401_70_dialog_content = "Então, mesmo que você erre, não precisa se preocupar em machucar alguém.",
  ui_story_32110401_71_dialog_content = "Certo... mas qual o problema com isso?",
  ui_story_32110401_72_dialog_content = "Você já não considerou que, por estar sempre treinando em áreas vazias, contra alvos sem vida...",
  ui_story_32110401_73_dialog_content = "Você basicamente nunca precisou focar seu poder antes.",
  ui_story_32110401_74_dialog_content = "(!!!)",
  ui_story_32110401_75_dialog_content = "Dessa vez, você tem que acertar a garrafa na minha cabeça...",
  ui_story_32110401_76_dialog_content = "Se você não quer que eu me machuque, é isso.",
  ui_story_32110401_77_dialog_content = "PlayerName... isso realmente faz muito sentido.",
  ui_story_32110401_78_dialog_content = "Eu não posso voltar atrás agora!",
  ui_story_32110401_79_dialog_content = "(Eu não posso cometer erros desta vez... Eu não posso me dar ao luxo de estragar tudo...)",
  ui_story_32110401_80_dialog_content = "(Apenas como a Srta. Vice disse, bloqueie todos os pensamentos desnecessários...)",
  ui_story_32110401_81_dialog_content = "(Somente ao fundir sua consciência com os cristais de gelo, você poderá ter sucesso...)",
  ui_story_32110401_82_dialog_content = "E lembre-se—use a quantidade mínima de energia...",
  ui_story_32110401_83_dialog_content = "Vamos dar cor à neve!",
  ui_story_32110401_84_dialog_content = "Consegui?",
  ui_story_32110401_85_dialog_content = "Ufa... Foi o que eu pensei.",
  ui_story_32110401_86_dialog_content = "Zarya, não é que você não seja bom com precisão - você é apenas muito bom em liberar seu poder.",
  ui_story_32110401_87_dialog_content = "O que isso significa?",
  ui_story_32110401_88_dialog_content = "Isso significa que você não precisa se preocupar em fazer o máximo para controlar sua precisão como todo mundo faz...",
  ui_story_32110401_89_dialog_content = "Mas você precisa reduzir seu poder.",
  ui_story_32110401_90_dialog_content = "É como servir café - é naturalmente mais fácil derramar muito café quando a sua lata tem uma abertura larga.",
  ui_story_32110401_91_dialog_content = "... Meu poder... tem uma abertura ampla?",
  ui_story_32110401_92_dialog_content = "Isso mesmo. Então, eu aconselho você a usar métodos de combate mais rápidos e flexíveis quando estiver em batalha.",
  ui_story_32110401_93_dialog_content = "Isso deve reduzir consideravelmente suas chances de cometer um erro.",
  ui_story_32110401_94_dialog_content = "Hmm... Entendi! Da próxima vez, vou manter isso em mente e tentar fazer o mesmo novamente!",
  ui_story_32110401_95_dialog_content = "Uau, e você nem sequer me respondeu... Parece que não foi só a sua habilidade que cresceu hoje - sua personalidade também parece ter evoluído...",
  ui_story_32110401_96_dialog_content = "O que você está dizendo, PlayerName?",
  ui_story_32110401_97_dialog_content = "Você quer dizer... Eu cresci de outra maneira, além de melhorar meus Luminatics?",
  ui_story_32110401_98_dialog_content = "Hum, sim... E aí?",
  ui_story_32110401_99_dialog_content = "Então você acha que eu sou mais ou menos uma senhora madura agora, é isso?",
  ui_story_32110401_100_dialog_content = "Hã? Por que você diria isso...? Eu não acho, não...",
  ui_story_32110401_101_dialog_content = "Caramba! O que você está planejando fazer?!",
  ui_story_32110401_102_dialog_content = "... Meu querido PlayerName...",
  ui_story_32110401_103_dialog_content = "Você poderia continuar sendo meu parceiro de treinamento a partir de agora?",
  ui_story_32110401_104_dialog_content = "Afinal, quando tenho você como alvo para treino, é quando minha mente está mais focada...",
  ui_story_32110401_105_dialog_content = "Pleeeeease!",
  ui_story_32110401_106_dialog_content = "... Eu preciso pensar sobre isso!",
  ui_story_32110601_1_dialog_content = "(Quando eu era criança, frequentemente ficava sozinho em casa.)",
  ui_story_32110601_2_dialog_content = "(Minha irmã tinha que sair para patrulhar e não podia ficar comigo o tempo todo. As outras crianças também não brincavam comigo.)",
  ui_story_32110601_3_dialog_content = "(Havia apenas algumas coisas na vida que podiam me fazer sorrir naquela época, e a maioria delas estava no livro de histórias que minha irmã me deu.)",
  ui_story_32110601_4_dialog_content = "(O livro falava do gelo de Northland - de como ele se tornava sólido e forte, mas se transformava em água do mar quente quando exposto ao mundo exterior.)",
  ui_story_32110601_5_dialog_content = "(Minha irmã também costumava me dizer que poderíamos colocar nossos trajes de banho e visitar aquela terra fascinante e misteriosa um dia.)",
  ui_story_32110601_6_dialog_content = "(Mas...)",
  ui_story_32110601_7_dialog_content = "<color=#e8d9bb>Espalhando—</color>",
  ui_story_32110601_8_dialog_content = "Zarya?",
  ui_story_32110601_9_dialog_content = "<size=45>Zarya?</size>",
  ui_story_32110601_10_dialog_content = "Ai...",
  ui_story_32110601_11_dialog_content = "E aí? Este é o lugar errado?",
  ui_story_32110601_12_dialog_content = "Isso não é o oceano daquele livro?",
  ui_story_32110601_13_dialog_content = "Isso não é o que está errado, PlayerName.",
  ui_story_32110601_14_dialog_content = "É só que... essa é a primeira vez que vejo um oceano sem gelo sólido com meus próprios olhos. É... impressionante.",
  ui_story_32110601_15_dialog_content = "É tão lindo...",
  ui_story_32110601_16_dialog_content = "O mundo exterior é enorme... Esta é apenas uma pequena parte dele.",
  ui_story_32110601_17_dialog_content = "Tente colocar seus pés na água. Não há nada igual.",
  ui_story_32110601_18_dialog_content = "Ah? Assim?",
  ui_story_32110601_19_dialog_content = "Ah—",
  ui_story_32110601_20_dialog_content = "O que você acha? É uma sensação boa, né?",
  ui_story_32110601_21_dialog_content = "Não é exatamente como as fontes termais de Northland, mas ainda é muito bom... É tão quentinho.",
  ui_story_32110601_22_dialog_content = "Costumava tomar banho nas termas em Northland...",
  ui_story_32110601_23_dialog_content = "Os ventos em Northland são tão frios e cortantes. Minha irmã se recusaria a sair da aconchegante fonte termal.",
  ui_story_32110601_24_dialog_content = "Mas aqui é diferente. O vento é tão suave.",
  ui_story_32110601_25_dialog_content = "Mesmo que eu nadasse sob a brisa do oceano, não sentiria aquele frio cortante.",
  ui_story_32110601_26_dialog_content = "Se ao menos ela...",
  ui_story_32110601_27_dialog_content = "<color=#e8d9bb>Pitter-patter—</color>",
  ui_story_32110601_28_dialog_content = "Huh? Começou a chover de repente!",
  ui_story_32110601_29_dialog_content = "Mesmo depois de pegar emprestado todas essas bonecas ensolaradas de Hiiro e os outros...",
  ui_story_32110601_30_dialog_content = "Cinquenta deles não foram suficientes?!",
  ui_story_32110601_31_dialog_content = "Talvez... devêssemos encerrar por hoje?",
  ui_story_32110601_32_dialog_content = "O que você tá olhando?",
  ui_story_32110601_33_dialog_content = "Essa chuva...",
  ui_story_32110601_34_dialog_content = "A água da chuva aqui... É tão leve e não congela...",
  ui_story_32110601_35_dialog_content = "Você vai pegar um resfriado se continuar assim.",
  ui_story_32110601_36_dialog_content = "E as roupas novas que você está usando hoje vão ficar todas molhadas.",
  ui_story_32110601_37_dialog_content = "Eu não vou ficar doente com uma chuva quente como essa.",
  ui_story_32110601_38_dialog_content = "Comparado ao caixão congelante em que fui aprisionado por cem anos, essa chuva é como um carinho gentil da natureza.",
  ui_story_32110601_39_dialog_content = "É assim que eu imagino que seria sentir as fadas do meu livro de histórias a bater as asas sobre o meu rosto.",
  ui_story_32110601_40_dialog_content = "Ei, e agora você só senta?",
  ui_story_32110601_41_dialog_content = "Que punhado...",
  ui_story_32110601_42_dialog_content = "<color=#e8d9bb>A chuva cai em pitter-patter...</color>",
  ui_story_32110601_43_dialog_content = "<color=#e8d9bb>Zarya senta-se nas pedras, suas roupas molhadas pela chuva fria.</color>",
  ui_story_32110601_44_dialog_content = "Hum?",
  ui_story_32110601_45_dialog_content = "Ufa, ainda bem que eu trouxe um guarda-chuva...",
  ui_story_32110601_46_dialog_content = "PlayerName, você realmente não precisa se preocupar comigo.",
  ui_story_32110601_47_dialog_content = "Não estou preocupado! É só que...",
  ui_story_32110601_48_dialog_content = "... Uh, se você pegar um resfriado, No. 33 vai me culpar por não cuidar de você!",
  ui_story_32110601_49_dialog_content = "Pfft—",
  ui_story_32110601_50_dialog_content = "Então é isso, né? Isso realmente não é honesto da sua parte...",
  ui_story_32110601_51_dialog_content = "Apenas mova isso! Não pense por um segundo que eu sou tão imprudente quanto você...",
  ui_story_32110601_52_dialog_content = "Eu só tenho a sensação de que algo está pesando em sua mente.",
  ui_story_32110601_53_dialog_content = "Você tem se sentido um pouco estranho desde que viu o oceano.",
  ui_story_32110601_54_dialog_content = "Gostaria de me contar o que está te incomodando?",
  ui_story_32110601_55_dialog_content = "Como você sabe, o clima em Northland é bastante rigoroso, para dizer o mínimo.",
  ui_story_32110601_56_dialog_content = "Quando eu estava crescendo, um tempo nublado como este era um sinal de que logo cairia granizo.",
  ui_story_32110601_57_dialog_content = "Minha irmã correria de volta para casa para evitar o granizo, e até mesmo meu pai colocaria uma pausa temporária em seus negócios.",
  ui_story_32110601_58_dialog_content = "Isso foi há tanto tempo, mas ainda me lembro do som aterrorizante do granizo caindo.",
  ui_story_32110601_59_dialog_content = "Sempre que eu tinha medo, minha irmã pegava um livro de histórias e me confortava com contos do mundo exterior.",
  ui_story_32110601_60_dialog_content = "Ela acariciava minha cabeça e sussurrava suavemente no meu ouvido:",
  ui_story_32110601_61_dialog_content = "\"Zarya, você sabe que não precisa ter medo da chuva e da neve, certo? Há um mundo incrível esperando por você lá fora.\"",
  ui_story_32110601_62_dialog_content = "\"Há lugares onde o mar não congela e a chuva é suave e reconfortante.\"",
  ui_story_32110601_63_dialog_content = "\"Se tivermos a chance, vamos vestir nossos trajes de banho e nadar em um belo paraíso exótico algum dia.\"",
  ui_story_32110601_64_dialog_content = "E agora...",
  ui_story_32110601_65_dialog_content = "Aqui estou.",
  ui_story_32110601_66_dialog_content = "Onde o mar nunca congela... vestindo meu traje de banho...",
  ui_story_32110601_67_dialog_content = "Mas não há ninguém aqui para celebrar comigo a realização desse sonho.",
  ui_story_32110601_68_dialog_content = "Todos na sua família eram tão interessados no mundo externo quanto você?",
  ui_story_32110601_69_dialog_content = "Eu acho... que eram.",
  ui_story_32110601_70_dialog_content = "Minha irmã, é claro, sempre quis me mostrar o mundo exterior, mas o trabalho dela sempre atrapalhava.",
  ui_story_32110601_71_dialog_content = "Meu pai também era fascinado por produtos estrangeiros.",
  ui_story_32110601_72_dialog_content = "Quanto à minha mãe... ela morreu quando eu era jovem, então mal consigo me lembrar dela agora.",
  ui_story_32110601_73_dialog_content = "Mas ela sempre se apegava ao meu pai, que viajava com frequência e para lugares distantes, então eu suponho que ela provavelmente seria curiosa sobre o mundo mais amplo.",
  ui_story_32110601_74_dialog_content = "Então, você ainda não cumpriu seu acordo com todos eles?",
  ui_story_32110601_75_dialog_content = "Hum?",
  ui_story_32110601_76_dialog_content = "Depois que você deixou Northland, em vez de se trancar no seu quarto, você escolheu caminhar lá fora.",
  ui_story_32110601_77_dialog_content = "Você saiu para ver o mundo que os enchia de tanta curiosidade e desejo de viajar.",
  ui_story_32110601_78_dialog_content = "Valorize o presente e o céu sempre estará limpo.",
  ui_story_32110601_79_dialog_content = "Heh, é a sua língua de prata em ação novamente...? Você realmente tem o dom da lábia.",
  ui_story_32110601_80_dialog_content = "Infelizmente, não parece que o tempo vai melhorar hoje, independentemente de quão bem-humorado você possa estar.",
  ui_story_32110601_81_dialog_content = "<color=#e8d9bb>Uma brisa suave sopra, fazendo com que as nuvens inquietas se dissipem tão rapidamente quanto se formaram.</color>",
  ui_story_32110601_82_dialog_content = "<color=#e8d9bb>Raios de sol atravessam as nuvens opressoras e iluminam a praia.</color>",
  ui_story_32110601_83_dialog_content = "Aha! É como se a chuva realmente começasse e parasse quando você manda...",
  ui_story_32110601_84_dialog_content = "Hmm, acho que eu estava errado... Será possível que você possa controlar o tempo com Luminatics?",
  ui_story_32110601_85_dialog_content = "Os Caelestites não podem usar Lumina.",
  ui_story_32110601_86_dialog_content = "Se você achou a chuva divertida, caminhar na praia vai te surpreender! Você ainda não experimentou, né?",
  ui_story_32110601_87_dialog_content = "eu não...",
  ui_story_32110601_88_dialog_content = "Bem, nesse caso, vamos.",
  ui_story_32110601_89_option_content = "Pegue a mão de Zarya",
  ui_story_32110601_90_dialog_content = "A brisa do mar soprando através do céu azul claro após a chuva é tão suave...",
  ui_story_32110601_91_dialog_content = "O som dos meus sapatos raspando na praia... Eu gosto desse som.",
  ui_story_32110601_92_dialog_content = "Minha irmã e os outros também vivenciaram essa mesma cena?",
  ui_story_32110601_93_dialog_content = "Cem anos se passaram desde que fizemos aquela promessa.",
  ui_story_32110601_94_dialog_content = "Será possível que eles já estiveram nesta praia antes?",
  ui_story_32110601_95_option_content = "Sim, muito provavelmente.",
  ui_story_32110601_96_dialog_content = "Acredito que eles devem ter vindo para esta praia.",
  ui_story_32110601_97_dialog_content = "Eles também devem ter sentido a suave brisa marinha após a chuva e respirado esse ar fresco do oceano.",
  ui_story_32110601_98_dialog_content = "Eles provavelmente visitaram muitos outros lugares também.",
  ui_story_32110601_99_dialog_content = "Caminhe nas pegadas deles e testemunhe o mundo exterior que eles já exploraram.",
  ui_story_32110601_100_dialog_content = "Além disso, você também gosta bastante do mundo exterior.",
  ui_story_32110601_101_dialog_content = "Sim, eu gosto.",
  ui_story_32110601_102_option_content = "Eles talvez não estivessem aqui antes.",
